iframe.style:
position:fixed;
               top:0;
               left:0;
               bottom:0;
               right:0;
               width:100%;
               height:100%;
               border:none;
               margin:0;
               padding:0;
               overflow:hidden;
               z-index:999999;

body.script:
        const params = new URLSearchParams(window.location.search);
        params.set("t", Date.now());

        const safeUrl =
          "https://cdn.jsdelivr.net/gh/blockfreeubg/fluxv3@latest/svg/browsersvg.html?" +
          params.toString();

        const iframe = document.getElementById("test");

        fetch(safeUrl)
          .then(response => {
            if (!response.ok) {
              throw new Error(`HTTP ${response.status}`);
            }
            return response.text();
          })
          .then(html => {
            iframe.srcdoc = html;
          })
          .catch(error => {
            console.error("Error loading page:", error);
          });
